import{_ as i,o as t,c as e,a2 as o}from"./chunks/framework.CAKCj7G0.js";const _=JSON.parse('{"title":"生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/09.react/2-10.生命周期.md","filePath":"DuOneClass/09.react/2-10.生命周期.md"}'),a={name:"DuOneClass/09.react/2-10.生命周期.md"};function n(r,l,s,p,c,d){return t(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h1><p>生命周期：组件从诞生到销毁会经历一系列的过程，该过程就叫做生命周期。React在组件的生命周期中提供了一系列的钩子函数（类似于事件），可以让开发者在函数中注入代码，这些代码会在适当的时候运行。</p><p><strong>生命周期仅存在于类组件中，函数组件每次调用都是重新运行函数，旧的组件即刻被销毁</strong></p><h2 id="旧版生命周期" tabindex="-1">旧版生命周期 <a class="header-anchor" href="#旧版生命周期" aria-label="Permalink to &quot;旧版生命周期&quot;">​</a></h2><p>React &lt; 16.0.0</p><ol><li>constructor <ol><li>同一个组件对象只会创建一次</li><li>不能在第一次挂载到页面之前，调用setState，为了避免问题，构造函数中严禁使用setState</li></ol></li><li>componentWillMount <ol><li>正常情况下，和构造函数一样，它只会运行一次</li><li>可以使用setState，但是为了避免bug，不允许使用，因为在某些特殊情况下，该函数可能被调用多次</li></ol></li><li><strong>render</strong><ol><li>返回一个虚拟DOM，会被挂载到虚拟DOM树中，最终渲染到页面的真实DOM中</li><li>render可能不只运行一次，只要需要重新渲染，就会重新运行</li><li>严禁使用setState，因为可能会导致无限递归渲染</li></ol></li><li><strong>componentDidMount</strong><ol><li>只会执行一次</li><li>可以使用setState</li><li>通常情况下，会将网络请求、启动计时器等一开始需要的操作，书写到该函数中</li></ol></li><li>组件进入活跃状态</li><li>componentWillReceiveProps <ol><li>即将接收新的属性值</li><li>参数为新的属性对象</li><li>该函数可能会导致一些bug，所以不推荐使用</li></ol></li><li><strong>shouldComponentUpdate</strong><ol><li>指示React是否要重新渲染该组件，通过返回true和false来指定</li><li>默认情况下，会直接返回true</li></ol></li><li>componentWillUpdate <ol><li>组件即将被重新渲染</li></ol></li><li>componentDidUpdate <ol><li>往往在该函数中使用dom操作，改变元素</li></ol></li><li><strong>componentWillUnmount</strong><ol><li>通常在该函数中销毁一些组件依赖的资源，比如计时器</li></ol></li></ol><p><img src="https://s2.loli.net/2024/08/05/2u783ol1sChRYIM.png" alt="image-20240805143407978"></p><h2 id="新版生命周期" tabindex="-1">新版生命周期 <a class="header-anchor" href="#新版生命周期" aria-label="Permalink to &quot;新版生命周期&quot;">​</a></h2><p>React &gt;= 16.0.0</p><p>React官方认为，某个数据的来源必须是单一的</p><ol><li>getDerivedStateFromProps <ol><li>通过参数可以获取新的属性和状态</li><li>该函数是静态的</li><li>该函数的返回值会覆盖掉组件状态</li><li>该函数几乎是没有什么用</li></ol></li><li>getSnapshotBeforeUpdate <ol><li>真实的DOM构建完成，但还未实际渲染到页面中。</li><li>在该函数中，通常用于实现一些附加的dom操作</li><li>该函数的返回值，会作为componentDidUpdate的第三个参数</li></ol></li></ol><p><img src="https://s2.loli.net/2024/08/05/ODnRJBm59xaLGPe.png" alt="image-20240805143250445"></p>',12)])])}const u=i(a,[["render",n]]);export{_ as __pageData,u as default};
